// TypeScript streaming helper example
import { RedwoodClient } from '@redwood/inference';

const client = new RedwoodClient({ apiKey: process.env.RW_KEY, compat: { progressive_tool_streaming: true } });

async function callTool() {
  const stream = client.invokeToolStream('data-extract', { input: '...'}, {schema: '{\"type\":\"object\",\"properties\":{\"rows\":{\"type\":\"array\"}}}' });
  const recon = new StreamToolReconstructor(stream);
  for await (const msg of recon) {
    if (msg.type === 'progress') console.log('progress chunk', msg.part);
    if (msg.type === 'result') {
      // typed as T via generic: T = {rows: Array<Record<string, any>>}
      const result = msg.value;
      console.log('final result', result.rows.length);
    }
  }
}

callTool().catch(console.error);

code_examples_go:
// Go streaming consumer example
package main

import (
  "context"
  "fmt"
  rw "github.com/redwood/inference-go"
)

func main() {
  client := rw.NewClient(rw.ClientConfig{APIKey: "${RW_KEY}", Compat: rw.CompatConfig{ProgressiveToolStreaming: true}})
  ctx := context.Background()
  stream, err := client.InvokeToolStream(ctx, "csv-extract", map[string]interface{}{"input": "..."}, rw.WithSchema(`{"type":"object","properties":{"rows":{"type":"array"}}}`))
  if err != nil { panic(err) }
  recon := rw.NewStreamToolReconstructor(stream)
  for recon.Next() {
    msg := recon.Message()
    switch msg.Type {
    case rw.MsgTypeProgress:
      fmt.Println("progress", msg.Part)
    case rw.MsgTypeResult:
      fmt.Println("final rows", len(msg.Value.(map[string]interface{})["rows"].([]interface{})))
    }
  }
}
